import{_ as p,a0 as l,w as d,s as r,ao as o,I as n,x as e,a1 as t,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"網絡地址轉換（NAT）之報文跟蹤 | LCTT x X-CMD","titleTemplate":false,"description":"網絡地址轉換（NAT）之報文跟蹤 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"網絡地址轉換（NAT）之報文跟蹤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"網絡地址轉換（NAT）之報文跟蹤 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210104 Network address translation part 1 - packet tracing","title":"網絡地址轉換（NAT）之報文跟蹤","tag":"202105","desc":""},"relativePath":"202105/20210104 Network address translation part 1 - packet tracing.md","filePath":"[post].md"}'),c={name:"202105/20210104 Network address translation part 1 - packet tracing.md"};function h(g,a,u,k,b,f){const s=l("Link");return d(),r("div",null,[a[15]||(a[15]=o(`<h1 id="網絡地址轉換-nat-之報文跟蹤" tabindex="-1">網絡地址轉換（NAT）之報文跟蹤 <a class="header-anchor" href="#網絡地址轉換-nat-之報文跟蹤" aria-label="Permalink to “網絡地址轉換（NAT）之報文跟蹤”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202105/06/112410xhdkvvdajis3jhlj.jpg" alt=""></p><p>這是有關<ruby>網絡地址轉換<rt>network address translation</rt></ruby>（NAT）的系列文章中的第一篇。這一部分將展示如何使用 iptables/nftables 報文跟蹤功能來定位 NAT 相關的連接問題。</p><h3 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to “引言”">​</a></h3><p>網絡地址轉換（NAT）是一種將容器或虛擬機暴露在互聯網中的一種方式。傳入的連接請求將其目標地址改寫為另一個地址，隨後被路由到容器或虛擬機。相同的技術也可用於負載均衡，即傳入的連接被分散到不同的服務器上去。</p><p>當網絡地址轉換沒有按預期工作時，連接請求將失敗，會暴露錯誤的服務，連接最終出現在錯誤的容器中，或者請求超時，等等。調試此類問題的一種方法是檢查傳入請求是否與預期或已配置的轉換相匹配。</p><h3 id="連接跟蹤" tabindex="-1">連接跟蹤 <a class="header-anchor" href="#連接跟蹤" aria-label="Permalink to “連接跟蹤”">​</a></h3><p>NAT 不僅僅是修改 IP 地址或端口號。例如，在將地址 X 映射到 Y 時，無需添加新規則來執行反向轉換。一個被稱為 “conntrack” 的 netfilter 系統可以識別已有連接的回覆報文。每個連接都在 conntrack 系統中有自己的 NAT 狀態。反向轉換是自動完成的。</p><h3 id="規則匹配跟蹤" tabindex="-1">規則匹配跟蹤 <a class="header-anchor" href="#規則匹配跟蹤" aria-label="Permalink to “規則匹配跟蹤”">​</a></h3><p>nftables 工具（以及在較小的程度上，iptables）允許針對某個報文檢查其處理方式以及該報文匹配規則集合中的哪條規則。為了使用這項特殊的功能，可在合適的位置插入“跟蹤規則”。這些規則會選擇被跟蹤的報文。假設一個來自 IP 地址 C 的主機正在訪問一個 IP 地址是 S 以及端口是 P 的服務。我們想知道報文匹配了哪條 NAT 轉換規則，系統檢查了哪些規則，以及報文是否在哪裏被丟棄了。</p><p>由於我們要處理的是傳入連接，所以我們將規則添加到 prerouting 鈎子上。prerouting 意味着內核尚未決定將報文發往何處。修改目標地址通常會使報文被系統轉發，而不是由主機自身處理。</p><h3 id="初始配置" tabindex="-1">初始配置 <a class="header-anchor" href="#初始配置" aria-label="Permalink to “初始配置”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nft &#39;add table inet trace_debug&#39;</span></span>
<span class="line"><span># nft &#39;add chain inet trace_debug trace_pre { type filter hook prerouting priority -200000; }&#39;</span></span>
<span class="line"><span># nft &quot;insert rule inet trace_debug trace_pre ip saddr $C ip daddr $S tcp dport $P tcp flags syn limit rate 1/second meta nftrace set 1&quot;</span></span></code></pre></div><p>第一條規則添加了一張新的規則表，這使得將來刪除和調試規則可以更輕鬆。一句 <code>nft delete table inet trace_debug</code> 命令就可以刪除調試期間臨時加入表中的所有規則和鏈。</p><p>第二條規則在系統進行路由選擇之前（<code>prerouting</code> 鈎子）創建了一個基本鈎子，並將其優先級設置為負數，以保證它在連接跟蹤流程和 NAT 規則匹配之前被執行。</p><p>然而，唯一最重要的部分是第三條規則的最後一段：<code>meta nftrace set 1</code>。這條規則會使系統記錄所有匹配這條規則的報文所關聯的事件。為了儘可能高效地查看跟蹤信息（提高信噪比），考慮對跟蹤的事件增加一個速率限制，以保證其數量處於可管理的範圍。一個好的選擇是限制每秒鐘最多一個報文或一分鐘最多一個報文。上述案例記錄了所有來自終端 <code>$C</code> 且去往終端 <code>$S</code> 的端口 <code>$P</code> 的所有 SYN 報文和 SYN/ACK 報文。限制速率的配置語句可以防範事件過多導致的洪泛風險。事實上，大多數情況下只記錄一個報文就足夠了。</p><p>對於 iptables 用户來講，配置流程是類似的。等價的配置規則類似於：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># iptables -t raw -I PREROUTING -s $C -d $S -p tcp --tcp-flags SYN SYN  --dport $P  -m limit --limit 1/s -j TRACE</span></span></code></pre></div><h3 id="獲取跟蹤事件" tabindex="-1">獲取跟蹤事件 <a class="header-anchor" href="#獲取跟蹤事件" aria-label="Permalink to “獲取跟蹤事件”">​</a></h3><p>原生 nft 工具的用户可以直接運行 <code>nft</code> 進入 nft 跟蹤模式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nft monitor trace</span></span></code></pre></div><p>這條命令會將收到的報文以及所有匹配該報文的規則打印出來（用 <code>CTRL-C</code> 來停止輸出）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trace id f0f627 ip raw prerouting  packet: iif &quot;veth0&quot; ether saddr ..</span></span></code></pre></div><p>我們將在下一章詳細分析該結果。如果你用的是 iptables，首先通過 <code>iptables –version</code> 命令檢查一下已安裝的版本。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span>
<span class="line"><span># iptables --version</span></span>
<span class="line"><span>iptables v1.8.5 (legacy)</span></span></code></pre></div><p><code>(legacy)</code> 意味着被跟蹤的事件會被記錄到內核的環形緩衝區中。你可以用 <code>dmesg</code> 或 <code>journalctl</code> 命令來查看這些事件。這些調試輸出缺少一些信息，但和新工具提供的輸出從概念上來講很類似。你將需要首先查看規則被記錄下來的行號，並與活躍的 iptables 規則集合手動關聯。如果輸出顯示 <code>(nf_tables)</code>，你可以使用 <code>xtables-monitor</code> 工具：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># xtables-monitor --trace</span></span></code></pre></div><p>如果上述命令僅顯示版本號，你仍然需要查看 <code>dmesg</code>/<code>journalctl</code> 的輸出。<code>xtables-monitor</code> 工具和 <code>nft</code> 監控跟蹤工具使用相同的內核接口。它們之間唯一的不同點就是，<code>xtables-monitor</code> 工具會用 <code>iptables</code> 的語法打印事件，且如果你同時使用了 <code>iptables-nft</code> 和 <code>nft</code>，它將不能打印那些使用了 maps/sets 或其他只有 nftables 才支持的功能的規則。</p><h3 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h3><p>我們假設需要調試一個到虛擬機/容器的端口不通的問題。<code>ssh -p 1222 10.1.2.3</code> 命令應該可以遠程連接那台服務器上的某個容器，但連接請求超時了。</p><p>你擁有運行那台容器的主機的登錄權限。現在登錄該機器並增加一條跟蹤規則。可通過前述案例查看如何增加一個臨時的調試規則表。跟蹤規則類似於這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nft &quot;insert rule inet trace_debug trace_pre ip daddr 10.1.2.3 tcp dport 1222 tcp flags syn limit rate 6/minute meta nftrace set 1&quot;</span></span></code></pre></div><p>在添加完上述規則後，運行 <code>nft monitor trace</code>，在跟蹤模式下啓動 nft，然後重試剛才失敗的 <code>ssh</code> 命令。如果規則集較大，會出現大量的輸出。不用擔心這些輸出，下一節我們會做逐行分析。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trace id 9c01f8 inet trace_debug trace_pre packet: iif &quot;enp0&quot; ether saddr .. ip saddr 10.2.1.2 ip daddr 10.1.2.3 ip protocol tcp tcp dport 1222 tcp flags == syn</span></span>
<span class="line"><span>trace id 9c01f8 inet trace_debug trace_pre rule ip daddr 10.2.1.2 tcp dport 1222 tcp flags syn limit rate 6/minute meta nftrace set 1 (verdict continue)</span></span>
<span class="line"><span>trace id 9c01f8 inet trace_debug trace_pre verdict continue</span></span>
<span class="line"><span>trace id 9c01f8 inet trace_debug trace_pre policy accept</span></span>
<span class="line"><span>trace id 9c01f8 inet nat prerouting packet: iif &quot;enp0&quot; ether saddr .. ip saddr 10.2.1.2 ip daddr 10.1.2.3 ip protocol tcp  tcp dport 1222 tcp flags == syn</span></span>
<span class="line"><span>trace id 9c01f8 inet nat prerouting rule ip daddr 10.1.2.3  tcp dport 1222 dnat ip to 192.168.70.10:22 (verdict accept)</span></span>
<span class="line"><span>trace id 9c01f8 inet filter forward packet: iif &quot;enp0&quot; oif &quot;veth21&quot; ether saddr .. ip daddr 192.168.70.10 .. tcp dport 22 tcp flags == syn tcp window 29200</span></span>
<span class="line"><span>trace id 9c01f8 inet filter forward rule ct status dnat jump allowed_dnats (verdict jump allowed_dnats)</span></span>
<span class="line"><span>trace id 9c01f8 inet filter allowed_dnats rule drop (verdict drop)</span></span>
<span class="line"><span>trace id 20a4ef inet trace_debug trace_pre packet: iif &quot;enp0&quot; ether saddr .. ip saddr 10.2.1.2 ip daddr 10.1.2.3 ip protocol tcp tcp dport 1222 tcp flags == syn</span></span></code></pre></div><h3 id="對跟蹤結果作逐行分析" tabindex="-1">對跟蹤結果作逐行分析 <a class="header-anchor" href="#對跟蹤結果作逐行分析" aria-label="Permalink to “對跟蹤結果作逐行分析”">​</a></h3><p>輸出結果的第一行是觸發後續輸出的報文編號。這一行的語法與 nft 規則語法相同，同時還包括了接收報文的首部字段信息。你也可以在這一行找到接收報文的接口名稱（此處為 <code>enp0</code>）、報文的源和目的 MAC 地址、報文的源 IP 地址（可能很重要 - 報告問題的人可能選擇了一個錯誤的或非預期的主機），以及 TCP 的源和目的端口。同時你也可以在這一行的開頭看到一個“跟蹤編號”。該編號標識了匹配跟蹤規則的特定報文。第二行包括了該報文匹配的第一條跟蹤規則：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trace id 9c01f8 inet trace_debug trace_pre rule ip daddr 10.2.1.2 tcp dport 1222 tcp flags syn limit rate 6/minute meta nftrace set 1 (verdict continue)</span></span></code></pre></div><p>這就是剛添加的跟蹤規則。這裏顯示的第一條規則總是激活報文跟蹤的規則。如果在這之前還有其他規則，它們將不會在這裏顯示。如果沒有任何跟蹤輸出結果，説明沒有抵達這條跟蹤規則，或者沒有匹配成功。下面的兩行表明沒有後續的匹配規則，且 <code>trace_pre</code> 鈎子允許報文繼續傳輸（判定為接受）。</p><p>下一條匹配規則是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trace id 9c01f8 inet nat prerouting rule ip daddr 10.1.2.3  tcp dport 1222 dnat ip to 192.168.70.10:22 (verdict accept)</span></span></code></pre></div><p>這條 DNAT 規則設置了一個到其他地址和端口的映射。規則中的參數 <code>192.168.70.10</code> 是需要收包的虛擬機的地址，目前為止沒有問題。如果它不是正確的虛擬機地址，説明地址輸入錯誤，或者匹配了錯誤的 NAT 規則。</p><h3 id="ip-轉發" tabindex="-1">IP 轉發 <a class="header-anchor" href="#ip-轉發" aria-label="Permalink to “IP 轉發”">​</a></h3><p>通過下面的輸出我們可以看到，IP 路由引擎告訴 IP 協議棧，該報文需要被轉發到另一個主機：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trace id 9c01f8 inet filter forward packet: iif &quot;enp0&quot; oif &quot;veth21&quot; ether saddr .. ip daddr 192.168.70.10 .. tcp dport 22 tcp flags == syn tcp window 29200</span></span></code></pre></div><p>這是接收到的報文的另一種呈現形式，但和之前相比有一些有趣的不同。現在的結果有了一個輸出接口集合。這在之前不存在的，因為之前的規則是在路由決策之前（<code>prerouting</code> 鈎子）。跟蹤編號和之前一樣，因此仍然是相同的報文，但目標地址和端口已經被修改。假設現在還有匹配 <code>tcp dport 1222</code> 的規則，它們將不會對現階段的報文產生任何影響了。</p><p>如果該行不包含輸出接口（<code>oif</code>），説明路由決策將報文路由到了本機。對路由過程的調試屬於另外一個主題，本文不再涉及。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trace id 9c01f8 inet filter forward rule ct status dnat jump allowed_dnats (verdict jump allowed_dnats)</span></span></code></pre></div><p>這條輸出表明，報文匹配到了一個跳轉到 <code>allowed_dnats</code> 鏈的規則。下一行則説明了連接失敗的根本原因：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trace id 9c01f8 inet filter allowed_dnats rule drop (verdict drop)</span></span></code></pre></div><p>這條規則無條件地將報文丟棄，因此後續沒有關於該報文的日誌輸出。下一行則是另一個報文的輸出結果了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trace id 20a4ef inet trace_debug trace_pre packet: iif &quot;enp0&quot; ether saddr .. ip saddr 10.2.1.2 ip daddr 10.1.2.3 ip protocol tcp tcp dport 1222 tcp flags == syn</span></span></code></pre></div><p>跟蹤編號已經和之前不一樣，然後報文的內容卻和之前是一樣的。這是一個重傳嘗試：第一個報文被丟棄了，因此 TCP 嘗試了重傳。可以忽略掉剩餘的輸出結果了，因為它並沒有提供新的信息。現在是時候檢查那條鏈了。</p><h3 id="規則集合分析" tabindex="-1">規則集合分析 <a class="header-anchor" href="#規則集合分析" aria-label="Permalink to “規則集合分析”">​</a></h3><p>上一節我們發現報文在 inet filter 表中的一個名叫 <code>allowed_dnats</code> 的鏈中被丟棄。現在我們來查看它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nft list chain inet filter allowed_dnats</span></span>
<span class="line"><span>table inet filter {</span></span>
<span class="line"><span> chain allowed_dnats {</span></span>
<span class="line"><span>  meta nfproto ipv4 ip daddr . tcp dport @allow_in accept</span></span>
<span class="line"><span>  drop</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>接受 <code>@allow_in</code> 集的數據包的規則沒有顯示在跟蹤日誌中。我們通過列出元素的方式，再次檢查上述報文的目標地址是否在 <code>@allow_in</code> 集中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nft &quot;get element inet filter allow_in { 192.168.70.10 . 22 }&quot;</span></span>
<span class="line"><span>Error: Could not process rule: No such file or directory</span></span></code></pre></div><p>不出所料，地址-服務對並沒有出現在集合中。我們將其添加到集合中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nft &quot;add element inet filter allow_in { 192.168.70.10 . 22 }&quot;</span></span></code></pre></div><p>現在運行查詢命令，它將返回新添加的元素。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nft &quot;get element inet filter allow_in { 192.168.70.10 . 22 }&quot;</span></span>
<span class="line"><span>table inet filter {</span></span>
<span class="line"><span>   set allow_in {</span></span>
<span class="line"><span>      type ipv4_addr . inet_service</span></span>
<span class="line"><span>      elements = { 192.168.70.10 . 22 }</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>ssh</code> 命令現在應該可以工作，且跟蹤結果可以反映出該變化：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trace id 497abf58 inet filter forward rule ct status dnat jump allowed_dnats (verdict jump allowed_dnats)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>trace id 497abf58 inet filter allowed_dnats rule meta nfproto ipv4 ip daddr . tcp dport @allow_in accept (verdict accept)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>trace id 497abf58 ip postrouting packet: iif &quot;enp0&quot; oif &quot;veth21&quot; ether .. trace id 497abf58 ip postrouting policy accept</span></span></code></pre></div><p>這表明報文通過了轉發路徑中的最後一個鈎子 - <code>postrouting</code>。</p><p>如果現在仍然無法連接，問題可能處在報文流程的後續階段，有可能並不在 nftables 的規則集合範圍之內。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>本文介紹瞭如何通過 nftables 的跟蹤機制檢查丟包或其他類型的連接問題。本系列的下一篇文章將展示如何檢查連接跟蹤系統和可能與連接跟蹤流相關的 NAT 信息。</p><hr>`,68)),n("p",null,[a[1]||(a[1]=e("via: ",-1)),t(s,{href:"https://fedoramagazine.org/network-address-translation-part-1-packet-tracing/"},{default:i(()=>[...a[0]||(a[0]=[e("https://fedoramagazine.org/network-address-translation-part-1-packet-tracing/",-1)])]),_:1})]),n("p",null,[a[6]||(a[6]=e("作者：",-1)),t(s,{href:"https://fedoramagazine.org/author/strlen/"},{default:i(()=>[...a[2]||(a[2]=[e("Florian Westphal",-1)])]),_:1}),a[7]||(a[7]=e(" 選題：",-1)),t(s,{href:"https://github.com/lujun9972"},{default:i(()=>[...a[3]||(a[3]=[e("lujun9972",-1)])]),_:1}),a[8]||(a[8]=e(" 譯者：",-1)),t(s,{href:"https://github.com/cooljelly"},{default:i(()=>[...a[4]||(a[4]=[e("cooljelly",-1)])]),_:1}),a[9]||(a[9]=e(" 校對：",-1)),t(s,{href:"https://github.com/wxy"},{default:i(()=>[...a[5]||(a[5]=[e("wxy",-1)])]),_:1})]),n("p",null,[a[12]||(a[12]=e("本文由 ",-1)),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[10]||(a[10]=[e("LCTT",-1)])]),_:1}),a[13]||(a[13]=e(" 原創編譯，",-1)),t(s,{href:"https://linux.cn/"},{default:i(()=>[...a[11]||(a[11]=[e("Linux中國",-1)])]),_:1}),a[14]||(a[14]=e(" 榮譽推出",-1))])])}const C=p(c,[["render",h]]);export{v as __pageData,C as default};
